// ─── Static Params & Metadata ────────────────────────────────────────────

export function generateStaticParams() {
  return STUDIES.map((study) => ({ slug: study.slug }));
}

export function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  return (async () => {
    const { slug } = await params;
    const study = STUDIES.find((s) => s.slug === slug);
    if (!study) {
      return {
        title: 'Study Not Found',
        description: 'The requested research study could not be found.',
      };
    }
    return {
      title: study.metaTitle,
      description: study.metaDescription,
      alternates: { canonical: `${SITE_URL}/research/${study.slug}` },
      openGraph: {
        title: study.metaTitle,
        description: study.metaDescription,
        url: `${SITE_URL}/research/${study.slug}`,
        siteName: 'TheTaxCalc',
        type: 'article',
        publishedTime: '2026-01-15T08:00:00.000Z',
        authors: ['TheTaxCalc Research Team'],
      },
    };
  })();
}

// ─── JSON-LD Helpers ──────────────────────────────────────────────────────

function buildJsonLd(study: Study) {
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'BreadcrumbList',
        '@id': `${SITE_URL}/research/${study.slug}#breadcrumb`,
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'Home', item: SITE_URL },
          {
            '@type': 'ListItem',
            position: 2,
            name: 'Research',
            item: `${SITE_URL}/research`,
          },
          {
            '@type': 'ListItem',
            position: 3,
            name: study.title,
            item: `${SITE_URL}/research/${study.slug}`,
          },
        ],
      },
      {
        '@type': 'FAQPage',
        '@id': `${SITE_URL}/research/${study.slug}#faq`,
        mainEntity: study.faqs.map((f) => ({
          '@type': 'Question',
          name: f.question,
          acceptedAnswer: { '@type': 'Answer', text: f.answer },
        })),
      },
      {
        '@type': 'ScholarlyArticle',
        '@id': `${SITE_URL}/research/${study.slug}#article`,
        headline: study.title,
        description: study.metaDescription,
        datePublished: '2026-01-15',
        dateModified: '2026-01-15',
        inLanguage: 'en-US',
        url: `${SITE_URL}/research/${study.slug}`,
        author: {
          '@type': 'Organization',
          name: 'TheTaxCalc Research Team',
          url: `${SITE_URL}/about`,
        },
        publisher: {
          '@type': 'Organization',
          name: 'TheTaxCalc',
          url: SITE_URL,
          logo: {
            '@type': 'ImageObject',
            url: `${SITE_URL}/logo.svg`,
          },
        },
        about: study.category,
        keywords: ['tax research', '2026 taxes', study.category.toLowerCase()],
        mainEntityOfPage: {
          '@type': 'WebPage',
          '@id': `${SITE_URL}/research/${study.slug}`,
        },
      },
      ...study.datasets.map((d, i) => ({
        '@type': 'Dataset',
        '@id': `${SITE_URL}/research/${study.slug}#dataset-${i + 1}`,
        name: d.name,
        description: d.description,
        creator: { '@type': 'Organization', name: d.creator },
        url: d.url,
        inLanguage: 'en-US',
        license: 'https://creativecommons.org/licenses/by/4.0/',
        isAccessibleForFree: true,
        distribution: {
          '@type': 'DataDownload',
          encodingFormat: 'text/html',
          contentUrl: d.url,
        },
      })),
    ],
  };
}

